INSERT INTO `agent_events` VALUES ('evt_1d11a484','demo_agent_lithium','碳酸锂价格上涨 60.00%','监测到碳酸锂最新价格由 12.50 变为 20.00，单次波动 +60.00%，已触发价格传导分析。','seed','','2026-04-15','high','[\"碳酸锂\",\"电池电解液\",\"正极材料\",\"电芯\",\"电池\",\"新能源汽车\"]','project_public','2026-04-16 14:15:12'),('evt_2179242e','demo_agent_lithium','碳酸锂价格上涨 60.00%','监测到碳酸锂最新价格由 12.50 变为 20.00，单次波动 +60.00%，已触发价格传导分析。','seed','','2026-04-15','high','[\"碳酸锂\",\"电池电解液\",\"正极材料\",\"电芯\",\"电池\",\"新能源汽车\"]','project_public','2026-04-16 17:45:44'),('evt_4ab146d7','agent_995e16db','中芯国际联合国内设备商，在28nm工艺关键设备上取得验证突破','据产业链消息，中芯国际与一家国内头部半导体设备厂商合作，其某款用于28nm制程的刻蚀设备已通过中芯国际的生产线验证，并开始小批量导入。这是国产替代的重要一步。','中国证券报','','2026-04-09','medium','[]','project_public','2026-04-11 10:43:19'),('evt_4c7dd76b','agent_995e16db','美国对华半导体设备出口管制出现新动向，中芯国际供应链国产化进程受关注','近期有外媒报道，美国可能进一步收紧对华先进半导体制造设备的出口许可。此背景下，市场密切关注中芯国际在设备、材料等环节的国产替代进展及供应链安全。','财联社','','2026-04-03','high','[]','project_public','2026-04-11 10:43:19'),('evt_533d996a','demo_agent_lithium','碳酸锂价格上涨 60.00%','监测到碳酸锂最新价格由 12.50 变为 20.00，单次波动 +60.00%，已触发价格传导分析。','seed','','2026-04-15','high','[\"碳酸锂\",\"电池电解液\",\"正极材料\",\"电芯\",\"电池\",\"新能源汽车\"]','project_public','2026-04-16 10:56:08'),('evt_7a6dff8c','demo_agent_lithium','碳酸锂价格上涨 52.00%','监测到碳酸锂最新价格由 12.50 变为 19.00，单次波动 +52.00%，已触发价格传导分析。','seed','','2026-04-15','high','[\"碳酸锂\",\"电池电解液\",\"正极材料\",\"电芯\",\"电池\",\"新能源汽车\"]','project_public','2026-04-15 22:46:54'),('evt_8c373315','demo_agent_lithium','碳酸锂价格上涨 60.00%','监测到碳酸锂最新价格由 12.50 变为 20.00，单次波动 +60.00%，已触发价格传导分析。','seed','','2026-04-15','high','[\"碳酸锂\",\"电池电解液\",\"正极材料\",\"电芯\",\"电池\",\"新能源汽车\"]','project_public','2026-04-16 17:54:04'),('evt_be077f2b','demo_agent_lithium','碳酸锂价格上涨 60.00%','监测到碳酸锂最新价格由 12.50 变为 20.00，单次波动 +60.00%，已触发价格传导分析。','seed','','2026-04-15','high','[\"碳酸锂\",\"电池电解液\",\"正极材料\",\"电芯\",\"电池\",\"新能源汽车\"]','project_public','2026-04-15 22:48:00'),('evt_c6dda372','agent_995e16db','华为等国内设计公司加大中芯国际订单，成熟制程产能利用率维持高位','行业调研显示，2026年第一季度，包括华为海思在内的多家国内芯片设计公司，增加了对中芯国际成熟制程（特别是55nm至28nm）的投片量，公司相关产线维持高负荷运转。','21世纪经济报道','','2026-04-05','medium','[]','project_public','2026-04-11 10:43:19'),('evt_c9bf1a37','agent_995e16db','中芯国际宣布14纳米及以上工艺节点扩产计划，以应对国内需求增长','中芯国际在近期投资者交流会上透露，为满足国内客户对成熟制程（14nm及以上）的强劲需求，公司已启动新一轮扩产计划，重点提升28nm及40nm等节点的产能。','证券时报','','2026-04-07','high','[]','project_public','2026-04-11 10:43:19'),('evt_e91c9eb8','demo_agent_lithium','碳酸锂价格上涨 60.00%','监测到碳酸锂最新价格由 12.50 变为 20.00，单次波动 +60.00%，已触发价格传导分析。','seed','','2026-04-15','high','[\"碳酸锂\",\"电池电解液\",\"正极材料\",\"电芯\",\"电池\",\"新能源汽车\"]','project_public','2026-04-16 14:14:57'),('evt_f37d09ac','demo_agent_lithium','碳酸锂价格上涨 60.00%','监测到碳酸锂最新价格由 12.50 变为 20.00，单次波动 +60.00%，已触发价格传导分析。','seed','','2026-04-15','high','[\"碳酸锂\",\"电池电解液\",\"正极材料\",\"电芯\",\"电池\",\"新能源汽车\"]','project_public','2026-04-16 07:12:46');
