INSERT INTO `link_types` VALUES ('lt_battery_cell_aluminum_foil','电芯由铝箔组成','battery_cell','aluminum_foil','N:1','电芯生产过程中需要使用铝箔作为关键材料输入，同一种铝箔可服务多个电芯实例。',NULL,'2026-04-30 14:18:04','2026-04-30 14:18:04','unique_id','unique_id','active','project_public'),('lt_battery_cell_battery_electrolyte_1775655447785','电芯由电解液组成','battery_cell','battery_electrolyte','N:1','电芯的生产需要使用特定的电解液，电解液的类型和价格影响电芯的性能和成本',NULL,'2026-04-08 21:37:27','2026-04-20 14:00:38','unique_id','unique_id','active','project_public'),('lt_battery_cell_cathode_material_1775472265881','电芯由正极材料组成','battery_cell','cathode_material','N:1','电芯的制造需要使用特定的正极材料（如磷酸铁锂、三元材料等），同一种正极材料可用于多种电芯。',NULL,'2026-04-06 18:44:25','2026-04-20 14:00:38','unique_id','material_id','active','project_public'),('lt_battery_cell_copper_foil','电芯由铜箔组成','battery_cell','copper_foil','N:1','电芯生产过程中需要使用铜箔作为集流体材料，同一种铜箔可服务多个电芯实例。',NULL,'2026-04-30 14:18:04','2026-04-30 14:18:04','unique_id','unique_id','active','project_public'),('lt_battery_electrolyte_lithium_carbonate_1775655437902','电解液由碳酸锂组成','battery_electrolyte','lithium_carbonate','N:1','电解液（特别是锂离子电池电解液）的生产需要使用碳酸锂作为锂源，碳酸锂的价格影响电解液成本',NULL,'2026-04-08 21:37:17','2026-04-20 14:00:38','unique_id','unique_id','active','project_public'),('lt_battery_electrolyte_lithium_hexafluorophosphate','电解液由六氟磷酸锂组成','battery_electrolyte','lithium_hexafluorophosphate','N:1','电解液的生产需要使用六氟磷酸锂作为关键锂盐输入，同一种六氟磷酸锂可供多个电解液实例使用。',NULL,'2026-04-30 14:18:04','2026-04-30 14:18:04','unique_id','unique_id','active','project_public'),('lt_cathode_material_lithium_carbonate_1775472267480','正极材料消耗碳酸锂','cathode_material','lithium_carbonate','N:M','正极材料的生产需要消耗碳酸锂作为关键锂源，而碳酸锂也可用于生产多种不同的正极材料。',NULL,'2026-04-06 18:44:27','2026-04-11 10:12:16','material_id','unique_id','active','project_public'),('lt_cathode_material_lithium_iron_phosphate','正极材料由磷酸铁锂组成','cathode_material','lithium_iron_phosphate','N:1','正极材料的生产会使用磷酸铁锂作为关键材料输入，同一种磷酸铁锂可供多个正极材料实例使用。',NULL,'2026-04-30 14:18:04','2026-04-30 14:18:04','material_id','unique_id','active',